export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * Copilot Runtime for this harness.\n *\n * Shape comes from the Angular quickstart's Node runtime server\n * (https://docs.copilotkit.ai/angular/mastra/quickstart), with the agent bound\n * to the Mastra backend in `../backend` — the Angular/Mastra quickstart defers\n * the backend step to \"register this backend as the `default` agent\".\n *\n * `@ag-ui/mastra` is the bridge: `MastraAgent` wraps a Mastra agent and speaks\n * AG-UI to the runtime, so no generic `HttpAgent` is needed. The Mastra\n * instance is imported directly from `backend/src/mastra`, so\n * `MastraAgent.getLocalAgent` runs the agent in THIS process — there is no\n * second server and no HTTP hop to the agent.\n *\n * `default` and `support` resolve to the same Mastra agent under two ids, each\n * with its own `resourceId` so their memory does not collide. `support` exists\n * so the doc snippets that use `agentId=\"support\"` (Chat UI, Threads) run\n * verbatim.\n *\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\n * https://docs.copilotkit.ai/angular/mastra/backend/copilot-runtime\n */\nimport { createServer } from \"node:http\";\nimport { CopilotRuntime } from \"@copilotkit/runtime/v2\";\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\nimport { MastraAgent } from \"@ag-ui/mastra\";\nimport { mastra } from '../backend/src/mastra';\n\n// subagents : guarded supervisor import start\n// SELF-DEFINED — not from the docs. The sub-agents guide's code imports two\n// modules it never shows, so the supervisor cannot load. Importing it\n// statically would take the whole runtime down with it; this keeps the\n// failure to the `subagents` key and logs why.\nconst supervisorReady: Promise<boolean> = import(\n  '../backend/src/mastra/agents/subagents-supervisor'\n)\n  .then(({ subagentsSupervisorAgent }) => {\n    mastra.addAgent(subagentsSupervisorAgent, 'subagentsSupervisorAgent');\n    return true;\n  })\n  .catch((err: unknown) => {\n    console.error('[subagents] supervisor failed to load:', err);\n    return false;\n  });\n// subagents : guarded supervisor import end\n\nconst runtime = new CopilotRuntime({\n  agents: async () => ({\n    default: MastraAgent.getLocalAgent({\n      mastra,\n      agentId: 'myAgent',\n      resourceId: 'agent-1',\n    }),\n    support: MastraAgent.getLocalAgent({\n      mastra,\n      agentId: 'myAgent',\n      resourceId: 'agent-2',\n    }),\n    // copilot-runtime : \"Which name identifies an agent\" — the guide's\n    // `<copilot-chat agentId=\"my_agent\" />` addresses this key.\n    my_agent: MastraAgent.getLocalAgent({\n      mastra,\n      agentId: 'myAgent',\n      resourceId: 'agent-3',\n    }),\n    // background-tasks : the guide does not name a runtime key; this one is\n    // the agent's own id.\n    'background-agents': MastraAgent.getLocalAgent({\n      mastra,\n      agentId: 'backgroundAgentsAgent',\n      resourceId: 'agent-4',\n    }),\n    // ag-ui : `research-agent` is used by the AG-UI guide and defined nowhere;\n    // it is one more alias of this harness's agent, like `default`/`support`.\n    'research-agent': MastraAgent.getLocalAgent({\n      mastra,\n      agentId: 'myAgent',\n      resourceId: 'agent-6',\n    }),\n    // subagents : registered only if the supervisor loaded.\n    ...((await supervisorReady)\n      ? {\n          subagents: MastraAgent.getLocalAgent({\n            mastra,\n            agentId: 'subagentsSupervisorAgent',\n            resourceId: 'agent-5',\n          }),\n        }\n      : {}),\n  }),\n  a2ui: {}\n});\n\n\nconst port = Number(process.env[\"PORT\"] ?? 8200);\n\ncreateServer(\n  createCopilotNodeListener({\n    runtime,\n    basePath: \"/api/copilotkit\",\n    cors: true,\n  }),\n).listen(port, () => {\n  console.log(\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\n  );\n});\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular/mastra/quickstart */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* ------------------------------------------------------------------ */\n/* Chat UI guide — \"Scope CSS changes\"                                 */\n/* https://docs.copilotkit.ai/angular/mastra/guides/chat-ui              */\n/* ------------------------------------------------------------------ */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n\n/* ------------------------------------------------------------------ */\n/* A2UI guide — \"Style rendered components\"                            */\n/* https://docs.copilotkit.ai/angular/mastra/guides/a2ui                 */\n/* ------------------------------------------------------------------ */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: white;\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: #eef2ff;\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: #dcfce7;\n  color: #166534;\n}\n.a2ui-status-warning {\n  background: #fef3c7;\n  color: #92400e;\n}\n.a2ui-status-error {\n  background: #fee2e2;\n  color: #991b1b;\n}\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { routes } from './app.routes';\n\n/**\n * Host function exposed to sandboxed Open Generative UI, verbatim from\n * https://docs.copilotkit.ai/angular/mastra/guides/frontend-tools-generative-ui\n */\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\n  name: 'setDashboardFilter',\n  description: 'Set the active dashboard filter',\n  parameters: z.object({ filter: z.string() }),\n  handler: async ({ filter }) => {\n    sessionStorage.setItem('dashboard-filter', filter);\n    return { applied: filter };\n  },\n};\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never talks to the Mastra agent directly.\n * The `MastraAgent` binding itself lives server-side in frontend/server.ts.\n *\n * `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are the A2UI and\n * generative-UI guide options. No `a2ui.catalog` is set yet — supplying one is\n * what actually registers the render_a2ui renderer, so A2UI stays inert until\n * a catalog is added. See README known issues.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8200/api/copilotkit',\n      a2ui: {\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      openGenerativeUI: {\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\n        // written. Cast at the array site, the same idiom the docs use for the\n        // equivalent `component` variance problem. See README known issues.\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\n      },\n    }),\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "/**\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\n * A2UI renderer activates automatically. No extra configuration is needed.\"\n *\n * The recovery thresholds the guide prescribes are set once in\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\n * https://docs.copilotkit.ai/angular/mastra/guides/a2ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class A2uiChatComponent {}\n",
  "src/app/features/ag-ui/ag-ui-chat.component.ts": "/**\n * SELF-DEFINED — not from the docs. Mounts the guide's two components beside a\n * chat on the same agent, so there is a run for them to observe. The guide's\n * components hard-code `research-agent`; the chat addresses that key too.\n *\n * https://docs.copilotkit.ai/angular/mastra/ag-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AgentEventsComponent } from './agent-events.component';\nimport { AgentStatusComponent } from './agent-status.component';\n\n@Component({\n  selector: 'app-ag-ui-chat',\n  imports: [CopilotChat, AgentStatusComponent, AgentEventsComponent],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <div\n        class=\"border-b border-slate-200 px-3 py-2 text-sm\"\n        data-testid=\"agent-status\"\n      >\n        <app-agent-status />\n        <app-agent-events />\n      </div>\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat agentId=\"research-agent\" />\n      </div>\n    </div>\n  `,\n})\nexport class AgUiChatComponent {}\n",
  "src/app/features/ag-ui/agent-events.component.ts": "/**\n * \"Subscribing to AG-UI events\".\n * https://docs.copilotkit.ai/angular/mastra/ag-ui\n *\n * The class members between the region markers are the guide's snippet,\n * unchanged. The guide gives only the class members; the decorator, imports and\n * class around them are SELF-DEFINED, the minimum needed to mount it. Output\n * goes to the browser console, as published.\n */\nimport { Component, DestroyRef, inject } from \"@angular/core\";\nimport { injectAgentStore } from \"@copilotkit/angular\";\n\n@Component({\n  selector: \"app-agent-events\",\n  template: ``,\n})\nexport class AgentEventsComponent {\n  // ag-ui : \"Subscribing to AG-UI events\" start\n  private readonly destroyRef = inject(DestroyRef);\n  readonly store = injectAgentStore(\"research-agent\");\n\n  constructor() {\n    const subscription = this.store().agent.subscribe({\n      onTextMessageContentEvent({ textMessageBuffer }) {\n        console.log(\"Streaming text:\", textMessageBuffer);\n      },\n      onToolCallEndEvent({ toolCallName, toolCallArgs }) {\n        console.log(\"Tool called:\", toolCallName, toolCallArgs);\n      },\n      onStateChanged({ agent }) {\n        console.log(\"State changed:\", agent.state);\n      },\n    });\n    this.destroyRef.onDestroy(() => subscription.unsubscribe());\n  }\n  // ag-ui : \"Subscribing to AG-UI events\" end\n}\n",
  "src/app/features/ag-ui/agent-status.component.ts": "/**\n * \"Accessing your agent with injectAgentStore\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/ag-ui\n *\n * The guide never defines `research-agent`; server.ts registers that runtime\n * key as another alias of this harness's agent (`myAgent`).\n */\nimport { Component, computed } from \"@angular/core\";\nimport { injectAgentStore } from \"@copilotkit/angular\";\n\n@Component({\n  selector: \"app-agent-status\",\n  template: `\n    <p>{{ messageCount() }} messages</p>\n    @if (store().isRunning()) {\n      <p>Agent is running…</p>\n    }\n  `,\n})\nexport class AgentStatusComponent {\n  readonly store = injectAgentStore(\"research-agent\");\n  readonly messageCount = computed(() => this.store().messages().length);\n}\n",
  "src/app/features/attachments/media-chat.component.ts": "/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/mastra/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n}\n",
  "src/app/features/background-tasks/background-task-card.component.ts": "/**\n * SELF-DEFINED — not from the docs.\n *\n * The guide's \"Render the activity card in your frontend\" step says the Angular\n * Showcase \"exports ready-to-register configs for both Mastra activity types\",\n * then publishes neither: both regions render as\n * `<!-- Angular Showcase snippet skipped: missing region mastra-activity-renderer-configs -->`.\n *\n * Shape follows the component in the registerRenderActivityMessage API reference\n * the guide links to (https://docs.copilotkit.ai/reference/angular/functions/registerRenderActivityMessage).\n * The content fields come from the `mastra-background-task` doc comment in\n * @ag-ui/mastra's type declarations; only the ones this card shows are parsed.\n * The config name mirrors the guide's `observationalMemoryActivityRendererConfig`.\n *\n * https://docs.copilotkit.ai/angular/mastra/background-tasks\n */\nimport { JsonPipe } from '@angular/common';\nimport { Component, input } from '@angular/core';\nimport type { AbstractAgent, ActivityMessage } from '@ag-ui/client';\nimport {\n  type ActivityRenderer,\n  type RenderActivityMessageConfig,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nconst backgroundTaskSchema = z.object({\n  taskId: z.string(),\n  toolName: z.string(),\n  status: z.enum([\n    'started',\n    'running',\n    'suspended',\n    'resumed',\n    'completed',\n    'failed',\n    'cancelled',\n  ]),\n  args: z.record(z.string(), z.unknown()).optional(),\n  result: z.unknown().optional(),\n  error: z.string().optional(),\n});\n\ntype BackgroundTaskContent = z.infer<typeof backgroundTaskSchema>;\n\n@Component({\n  selector: 'app-background-task-card',\n  template: `\n    @let task = content();\n    <article\n      class=\"my-2 rounded-lg border border-slate-200 bg-white p-3 text-sm\"\n      data-testid=\"background-task-card\"\n      [attr.data-status]=\"task.status\"\n    >\n      <p class=\"font-semibold text-slate-900\">{{ task.toolName }}</p>\n      <p class=\"text-slate-600\">\n        Status: <strong>{{ task.status }}</strong>\n      </p>\n      @if (task.args) {\n        <pre class=\"mt-1 whitespace-pre-wrap text-xs text-slate-600\">{{\n          task.args | json\n        }}</pre>\n      }\n      @if (task.status === 'completed') {\n        <pre class=\"mt-1 whitespace-pre-wrap text-xs text-slate-800\">{{\n          task.result | json\n        }}</pre>\n      }\n      @if (task.error) {\n        <p class=\"mt-1 text-red-700\">{{ task.error }}</p>\n      }\n    </article>\n  `,\n  imports: [JsonPipe],\n})\nexport class BackgroundTaskCardComponent\n  implements ActivityRenderer<BackgroundTaskContent>\n{\n  readonly activityType = input.required<string>();\n  readonly content = input.required<BackgroundTaskContent>();\n  readonly message = input.required<ActivityMessage>();\n  readonly agent = input<AbstractAgent>();\n}\n\nexport const backgroundTaskActivityRendererConfig: RenderActivityMessageConfig<BackgroundTaskContent> =\n  {\n    activityType: 'mastra-background-task',\n    content: backgroundTaskSchema,\n    component: BackgroundTaskCardComponent,\n  };\n",
  "src/app/features/background-tasks/background-tasks-chat.component.ts": "/**\n * SELF-DEFINED — not from the docs. The guide's registration snippet is missing\n * (`<!-- Angular Showcase snippet skipped: missing region mastra-activity-registration -->`);\n * its prose only says to \"register the config in an injection context\". This\n * does that in the constructor, the way the registerRenderActivityMessage API\n * reference does, beside the standard chat — the guide says \"the standard chat\n * surface renders registered activity messages inline, so no custom message\n * list is needed\".\n *\n * `background-agents` is the runtime key server.ts gives `backgroundAgentsAgent`;\n * the guide does not name one.\n *\n * https://docs.copilotkit.ai/angular/mastra/background-tasks\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, registerRenderActivityMessage } from '@copilotkit/angular';\n\nimport { backgroundTaskActivityRendererConfig } from './background-task-card.component';\n\n@Component({\n  selector: 'app-background-tasks-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat agentId=\"background-agents\" />\n    </div>\n  `,\n})\nexport class BackgroundTasksChatComponent {\n  constructor() {\n    registerRenderActivityMessage(backgroundTaskActivityRendererConfig);\n  }\n}\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\n *\n * The popup and the sidebar each get their own tab AND their own host\n * component. The guide declares both in a single component, but both render a\n * launcher at the same fixed coordinates, so mounting them together stacks two\n * launchers on one spot and the sidebar — rendered second — swallows every\n * click. The guide's combined component stays verbatim in\n * popup-sidebar.component.ts and is what the route page displays as source.\n *\n * Bindings on the split hosts are the guide's, unchanged.\n *\n * `.support-chat` is applied to the inline tab only. It is the scope class for\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\n * putting it on the shared host would tint the custom-message, popup, and\n * sidebar surfaces too, and each of those is meant to show its own default\n * styling.\n */\nimport { Component, signal } from '@angular/core';\n\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\nimport { PopupOnlyComponent } from './popup-only.component';\nimport { SidebarOnlyComponent } from './sidebar-only.component';\nimport { SupportChatComponent } from './support-chat.component';\n\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\n\n@Component({\n  selector: 'app-chat-ui-demo',\n  imports: [\n    SupportChatComponent,\n    CustomMessageChatComponent,\n    PopupOnlyComponent,\n    SidebarOnlyComponent,\n  ],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\n        @for (tab of tabs; track tab.id) {\n          <button\n            type=\"button\"\n            role=\"tab\"\n            [attr.aria-selected]=\"surface() === tab.id\"\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\n            [class]=\"\n              surface() === tab.id\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\n            \"\n            (click)=\"surface.set(tab.id)\"\n          >\n            {{ tab.label }}\n          </button>\n        }\n      </div>\n\n      <div class=\"min-h-0 flex-1\">\n        @switch (surface()) {\n          @case ('inline') {\n            <!-- Scope class for the guide's CSS block — this tab only. -->\n            <div class=\"support-chat h-full\">\n              <app-support-chat />\n            </div>\n          }\n          @case ('custom-message') {\n            <div class=\"h-full\">\n              <app-custom-message-chat />\n            </div>\n          }\n          @case ('popup') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-popup</code> opens from a floating launcher and\n                exposes a two-way <code>open</code> model, so the harness can\n                open it from here. It manages focus, closes on Escape, and\n                restores focus to the launcher.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\n              >\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\n              </button>\n              <app-popup-only #popupHost />\n            </div>\n          }\n          @case ('sidebar') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-sidebar</code> is docked to the right at 480px.\n                Compact viewports render it as a modal even when\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\n                docked sidebar can own the page margin at a time.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\n              >\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\n              </button>\n              <app-sidebar-only #sidebarHost />\n            </div>\n          }\n        }\n      </div>\n    </div>\n  `,\n})\nexport class ChatUiDemoComponent {\n  protected readonly surface = signal<Surface>('inline');\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\n    { id: 'inline', label: 'Inline chat' },\n    { id: 'custom-message', label: 'Custom assistant message' },\n    { id: 'popup', label: 'Popup' },\n    { id: 'sidebar', label: 'Sidebar' },\n  ];\n}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/guides/chat-ui\n */\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/mastra/guides/chat-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n",
  "src/app/features/chat-ui/popup-only.component.ts": "/**\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\n * Both render a launcher at the same fixed coordinates\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\n * stacks two launchers on one spot and the sidebar — rendered second — takes\n * every click. Splitting them is what makes each surface separately testable;\n * the combined component is kept verbatim in popup-sidebar.component.ts and\n * shown as the source on the route page.\n *\n * https://docs.copilotkit.ai/angular/mastra/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-only',\n  imports: [CopilotPopup],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n  `,\n})\nexport class PopupOnlyComponent {\n  readonly popupOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/mastra/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "/**\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * See popup-only.component.ts for why the guide's combined component is split\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\n *\n * https://docs.copilotkit.ai/angular/mastra/guides/chat-ui\n */\nimport { Component, signal } from '@angular/core';\nimport { CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-sidebar-only',\n  imports: [CopilotSidebar],\n  template: `\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class SidebarOnlyComponent {\n  readonly sidebarOpen = signal(false);\n}\n",
  "src/app/features/chat-ui/support-chat.component.ts": "/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n",
  "src/app/features/copilot-runtime/runtime-keys-chat.component.ts": "/**\n * \"Which name identifies an agent\" and \"The Default Agent\".\n * https://docs.copilotkit.ai/angular/mastra/copilot-runtime\n *\n * Left: no agentId, so the chat uses the runtime's `default` key. Right: the\n * guide's `<copilot-chat agentId=\"my_agent\" />`, verbatim — server.ts registers\n * `my_agent` as a key (bound to the Mastra record key `myAgent`), so the name\n * the frontend asks for is the agents-map key, not the agent's `name`\n * (\"My Agent\") or `id`.\n *\n * The side-by-side layout is SELF-DEFINED; it is not in the guide.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-runtime-keys-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 0.75rem\">\n      <section\n        style=\"flex: 1; min-width: 0; display: flex; flex-direction: column\"\n        data-testid=\"default-agent-chat\"\n      >\n        <h2 class=\"px-3 py-2 text-sm font-semibold\">default</h2>\n        <div style=\"flex: 1; min-height: 0\"><copilot-chat /></div>\n      </section>\n      <section\n        style=\"flex: 1; min-width: 0; display: flex; flex-direction: column\"\n        data-testid=\"my-agent-chat\"\n      >\n        <h2 class=\"px-3 py-2 text-sm font-semibold\">my_agent</h2>\n        <div style=\"flex: 1; min-height: 0\">\n          <copilot-chat agentId=\"my_agent\" />\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class RuntimeKeysChatComponent {}\n",
  "src/app/features/headless/headless-chat.component.ts": "/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/mastra/guides/threads-memory-attachments-headless\n */\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  readonly store = injectAgentStore('default');\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    await this.copilotKit.core.runAgent({ agent });\n  }\n}\n",
  "src/app/features/hitl/approval-card.component.ts": "/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/mastra/guides/human-in-the-loop\n */\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n",
  "src/app/features/hitl/approval-tools.service.ts": "/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/mastra/guides/human-in-the-loop\n */\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n  }\n}\n",
  "src/app/features/hitl/hitl-chat.component.ts": "/**\n * Puts the guide's three human-in-the-loop paths side by side: the decision\n * tool (registered by ApprovalToolsService, rendered inside the chat's\n * tool-call flow), the headless interrupt controller, and the store's own\n * controller — the last two rendered outside the chat and pointed at different\n * agents, as the guide's warning requires.\n * https://docs.copilotkit.ai/angular/mastra/guides/human-in-the-loop\n *\n * Injecting ApprovalToolsService is what constructs it, and construction is\n * what performs the `registerHumanInTheLoop` call.\n */\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\nimport { InterruptPanelComponent } from './interrupt-panel.component';\nimport { TicketApprovalComponent } from './ticket-approval.component';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat, InterruptPanelComponent, TicketApprovalComponent],\n  providers: [ApprovalToolsService],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <app-interrupt-panel />\n      <app-ticket-approval />\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService);\n}\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "/**\n * \"Handle an interrupt with a typed controller\", verbatim — the section the doc\n * called \"Handle an interrupt\" before 2026-08-21. The controller is headless, so\n * this panel renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/mastra/guides/human-in-the-loop\n *\n * The doc writes this call as `injectInterrupt<T>(\"default\")`, which is what\n * runs below. The object form stood in while `@copilotkit/angular@0.3.1` was\n * `latest`: it declared only `injectInterrupt(options?: InjectInterruptOptions)`\n * and no string overload. `0.4.0` publishes the overload, so the doc's form\n * compiles and the workaround is gone.\n */\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  protected readonly controller = injectInterrupt<ReviewRequest>('default');\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n",
  "src/app/features/hitl/ticket-approval.component.ts": "/**\n * \"Handle an interrupt from the store\", verbatim — the section added to the\n * guide on 2026-08-21.\n * https://docs.copilotkit.ai/angular/mastra/guides/human-in-the-loop\n *\n * Deferred until now: `AgentStore` shipped only `agent`, `isRunning`,\n * `messages` and `state` in `@copilotkit/angular@0.3.1`, so\n * `store().interruptController` did not exist for the four months the section\n * described it. `0.4.0` adds `readonly interruptController: InterruptController`\n * and the snippet compiles as published.\n *\n * One deviation: the doc injects the store for an agent named `ticketing`. No\n * such agent is registered here, and an unknown id resolves to a store whose\n * controller never sees an event — which would make this component look\n * healthy while testing nothing. It uses `support`, the second agent this\n * repo's runtime registers, which also keeps it off `default` and so honours\n * the guide's own warning against pointing `injectInterrupt` and\n * `store().interruptController` at one decision: the sibling\n * `app-interrupt-panel` holds `default`.\n */\nimport { Component } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-ticket-approval',\n  template: `\n    @let interrupts = store().interruptController;\n\n    @if (interrupts.hasInterrupt()) {\n      <section>\n        <p>{{ interrupts.interrupt()?.message }}</p>\n        <button type=\"button\" (click)=\"interrupts.resolve({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"interrupts.cancel()\">Reject</button>\n      </section>\n    }\n  `,\n})\nexport class TicketApprovalComponent {\n  protected readonly store = injectAgentStore('support');\n}\n",
  "src/app/features/inspector/inspector-chat.component.ts": "/**\n * A chat, so the Inspector has something to inspect.\n * https://docs.copilotkit.ai/angular/mastra/inspector\n *\n * Nothing here mounts the Inspector, and that is the page's whole point:\n * `@copilotkit/angular` mounts it for you \\u2014 the `CopilotKit` service creates\n * `cpk-web-inspector`, supplies the application's core, and appends it to\n * `document.body` after the first browser render.\n *\n * The page is emphatic that a hand-written mount must be deleted rather than\n * left alongside it: the framework reuses an existing `cpk-web-inspector`, but\n * a hand-rolled component's `DestroyRef.onDestroy` removes that element\n * unconditionally, so a route change tears out the Inspector the framework is\n * driving and it does not return without a full reload. This repo has never had\n * one, so there was nothing to retract.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-inspector-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class InspectorChatComponent {}\n",
  "src/app/features/inspector/inspector-probe.component.ts": "/**\n * The mount check the Inspector page needs and cannot get from the chat.\n * https://docs.copilotkit.ai/angular/mastra/inspector\n *\n * The page makes one claim that is checkable from the page itself:\n * `@copilotkit/angular` mounts the Inspector for you, by having the\n * `CopilotKit` service create a `cpk-web-inspector` element and append it to\n * `document.body` after the first browser render.\n *\n * Nothing here mounts anything, and that is the point — the guide is explicit\n * that a hand-written mount must be deleted, so this component only *observes*\n * whether the framework did the mounting and reports what it found. Without it\n * the only evidence in a recording is a launcher in the corner of a 1920×1080\n * frame, which is not something a viewer can read.\n *\n * Three outcomes, because the guide describes three situations:\n *   `mounted`   — exactly one element, the documented result.\n *   `duplicate` — more than one, the state a leftover hand-written mount\n *                 produces, and the failure the guide spends most of its space\n *                 warning about.\n *   `absent`    — none. A real reading rather than an error: on 0.4.0 the\n *                 element appears only once something *injects* `CopilotKit`,\n *                 because Angular constructs a root-provided service lazily, so\n *                 a route that configures CopilotKit but renders no consumer\n *                 has no Inspector.\n *\n * The probe runs after a paint rather than in the constructor: the element is\n * appended after the first browser render, so reading for it any earlier\n * reports a false negative — and on the server there is no document at all.\n */\nimport { isPlatformBrowser } from '@angular/common';\nimport {\n  Component,\n  DestroyRef,\n  PLATFORM_ID,\n  afterNextRender,\n  computed,\n  inject,\n  signal,\n} from '@angular/core';\n\n/** What the probe found, once it has actually looked. */\ntype ProbeResult = {\n  /** How many `cpk-web-inspector` elements are in the document. */\n  count: number;\n  /** Whether that element is a child of `document.body`, as documented. */\n  onBody: boolean;\n};\n\n@Component({\n  selector: 'app-inspector-probe',\n  template: `\n    <section\n      data-testid=\"probe\"\n      aria-labelledby=\"inspector-probe-title\"\n      class=\"flex flex-wrap items-center gap-3 border-b border-[var(--line)] bg-[var(--surface)] px-4 py-3 text-sm\"\n    >\n      <h2 id=\"inspector-probe-title\" class=\"sr-only\">Inspector mount check</h2>\n\n      <span\n        data-testid=\"probe-verdict\"\n        [attr.data-state]=\"state()\"\n        class=\"inline-flex items-center rounded-full px-2 py-0.5 text-xs font-semibold\"\n        [class]=\"badgeClass()\"\n      >\n        {{ badge() }}\n      </span>\n\n      <span class=\"text-[var(--muted)]\">{{ verdict() }}</span>\n\n      <span class=\"ml-auto text-xs text-[var(--muted)]\">\n        elements:\n        <span data-testid=\"probe-count\">{{ result()?.count ?? '—' }}</span>\n        · on document.body:\n        <span data-testid=\"probe-on-body\">{{\n          result() ? (result()!.onBody ? 'yes' : 'no') : '—'\n        }}</span>\n      </span>\n    </section>\n  `,\n})\nexport class InspectorProbeComponent {\n  private readonly isBrowser = isPlatformBrowser(inject(PLATFORM_ID));\n\n  protected readonly result = signal<ProbeResult | null>(null);\n\n  protected readonly state = computed<\n    'mounted' | 'absent' | 'duplicate' | 'pending'\n  >(() => {\n    const found = this.result();\n    if (!found) return 'pending';\n    if (found.count === 0) return 'absent';\n    if (found.count > 1) return 'duplicate';\n    return 'mounted';\n  });\n\n  protected readonly badge = computed(() => {\n    switch (this.state()) {\n      case 'mounted':\n        return 'cpk-web-inspector mounted';\n      case 'absent':\n        return 'no cpk-web-inspector';\n      case 'duplicate':\n        return 'more than one cpk-web-inspector';\n      default:\n        return 'checking…';\n    }\n  });\n\n  protected readonly badgeClass = computed(() =>\n    this.state() === 'mounted'\n      ? 'bg-emerald-50 text-emerald-700'\n      : 'bg-amber-50 text-amber-800',\n  );\n\n  protected readonly verdict = computed(() => {\n    switch (this.state()) {\n      case 'mounted':\n        return 'The framework mounted it. Nothing in this app creates the element.';\n      case 'absent':\n        return 'Nothing on this route has injected the CopilotKit service yet, so no element exists.';\n      case 'duplicate':\n        return 'A leftover hand-written mount produces exactly this — the guide says delete it.';\n      default:\n        return 'Waiting for the first browser render…';\n    }\n  });\n\n  constructor() {\n    if (!this.isBrowser) return;\n\n    afterNextRender(() => this.probe());\n\n    // Re-probed rather than read once, for two reasons: the element appears the\n    // moment a CopilotKit consumer is first mounted, which can be later than\n    // this component's own render; and a route change that destroyed a\n    // hand-written mount is exactly the scenario the guide warns takes the\n    // Inspector away without a reload.\n    const timer = setInterval(() => this.probe(), 1_000);\n    inject(DestroyRef).onDestroy(() => clearInterval(timer));\n  }\n\n  private probe(): void {\n    const elements = document.querySelectorAll('cpk-web-inspector');\n    this.result.set({\n      count: elements.length,\n      onBody: Array.from(elements).some(\n        (el) => el.parentElement === document.body,\n      ),\n    });\n  }\n}\n",
  "src/app/features/media/voice-chat.component.ts": "/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/mastra/guides/voice-multimodal\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\n  enabled: true,\n  accept: 'image/*,application/pdf',\n  maxSize: 10 * 1024 * 1024,\n};\n\n@Component({\n  selector: 'app-voice-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\n    </div>\n  `,\n})\nexport class VoiceChatComponent {\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\n}\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\n * Harness wrapper mounting the guide's memory list beside a chat, so the\n * `isAvailable()` gate can be observed against a live runtime.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { MemoryListComponent } from './memory-list.component';\n\n@Component({\n  selector: 'app-memory-demo',\n  imports: [CopilotChat, MemoryListComponent],\n  template: `\n    <div class=\"flex h-full gap-4 p-4\">\n      <section\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          injectMemories\n        </h2>\n        <app-memory-list />\n      </section>\n      <div class=\"min-w-0 flex-1\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class MemoryDemoComponent {}\n",
  "src/app/features/memory/memory-list.component.ts": "/**\n * \"Read and manage memory\", verbatim. The `isAvailable()` gate is the point of\n * the sample: a runtime may not provide the memory routes at all.\n * https://docs.copilotkit.ai/angular/mastra/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectMemories } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-memory-list',\n  template: `\n    @if (!memory.isAvailable()) {\n      <p>Memory is not available for this runtime.</p>\n    } @else {\n      @for (item of memory.memories(); track item.id) {\n        <article>\n          <p>{{ item.content }}</p>\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\n        </article>\n      }\n    }\n  `,\n})\nexport class MemoryListComponent {\n  readonly memory = injectMemories();\n\n  protected remove(id: string): void {\n    this.memory.removeMemory(id).catch(() => undefined);\n  }\n\n  protected addPreference(): void {\n    this.memory\n      .addMemory({\n        kind: 'operational',\n        content: 'Prefer concise status updates.',\n      })\n      .catch(() => undefined);\n  }\n}\n",
  "src/app/features/quickstart/quickstart-chat.ts": "/**\n * Quickstart step \"Add the chat UI\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/quickstart\n *\n * Only the selector and class name differ from the doc (which mounts this as\n * the app root); the template and imports are unchanged.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n",
  "src/app/features/shared-state/account-context.component.ts": "/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/mastra/guides/shared-state\n */\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <br>\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n",
  "src/app/features/shared-state/selection-context.component.ts": "/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/mastra/guides/shared-state\n */\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "/**\n * Mounts the guide's three surfaces against one chat: the read/write state\n * panel, the accessor-based context, and the directive-based context.\n * https://docs.copilotkit.ai/angular/mastra/guides/shared-state\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [\n    CopilotChat,\n    WorkspaceComponent,\n    AccountContextComponent,\n    SelectionContextComponent,\n  ],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n",
  "src/app/features/shared-state/workspace.component.ts": "/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/mastra/guides/shared-state\n */\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n    <br>\n     <button type=\"button\" (click)=\"setPriority('low')\">\n      Mark low priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n",
  "src/app/features/subagents/subagent-model.ts": "/**\n * SELF-DEFINED — not from the docs. The guide's frontend snippet uses\n * `SubAgentName` and `readDelegations` without showing either. The shape is\n * taken from the guide's own backend: `SubagentsAgentState` (demo-code tab)\n * and `buildDelegationPayload` in src/mastra/tools/subagents.ts.\n *\n * https://docs.copilotkit.ai/angular/mastra/multi-agent/subagents\n */\nexport type SubAgentName = 'research_agent' | 'writing_agent' | 'critique_agent';\n\nexport interface Delegation {\n  id: string;\n  sub_agent: SubAgentName;\n  task: string;\n  status: 'running' | 'completed' | 'failed';\n  result: string;\n}\n\n/** Reads the `delegations` slot out of agent state, tolerating its absence. */\nexport function readDelegations(state: unknown): Delegation[] {\n  if (typeof state !== 'object' || state === null) return [];\n  const delegations = (state as { delegations?: unknown }).delegations;\n  return Array.isArray(delegations) ? (delegations as Delegation[]) : [];\n}\n",
  "src/app/features/subagents/subagent-renderer-config.ts": "/**\n * SELF-DEFINED — not from the docs. The guide calls\n * `registerRenderToolCall(subAgentRendererConfig(name))` without showing\n * `subAgentRendererConfig` or the card it renders. The args schema is each\n * sub-agent tool's `inputSchema` (`{ task: string }`) from the guide's\n * src/mastra/tools/subagents.ts; the card follows the guide's own\n * \"Render a tool result\" component on the frontend-tools page.\n *\n * https://docs.copilotkit.ai/angular/mastra/multi-agent/subagents\n */\nimport { Component, input } from '@angular/core';\nimport {\n  type AngularToolCall,\n  type RenderToolCallConfig,\n  type ToolRenderer,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { type SubAgentName } from './subagent-model';\n\ntype SubAgentArgs = { task: string };\n\n@Component({\n  selector: 'app-subagent-call-card',\n  template: `\n    @let call = toolCall();\n    <article\n      class=\"my-2 rounded-lg border border-slate-200 bg-white p-3 text-sm\"\n      data-testid=\"subagent-call-card\"\n      [attr.data-status]=\"call.status\"\n    >\n      <p class=\"font-semibold text-slate-900\">{{ call.name }}</p>\n      <p class=\"text-slate-600\">{{ call.args.task ?? '…' }}</p>\n      @if (call.status === 'complete') {\n        <p class=\"mt-1 text-slate-800\">Done</p>\n      } @else {\n        <p class=\"mt-1 text-slate-500\">Delegating…</p>\n      }\n    </article>\n  `,\n})\nexport class SubAgentCallCardComponent implements ToolRenderer<SubAgentArgs> {\n  readonly toolCall = input.required<AngularToolCall<SubAgentArgs>>();\n}\n\nexport function subAgentRendererConfig(\n  name: SubAgentName,\n): RenderToolCallConfig<SubAgentArgs> {\n  return {\n    name,\n    args: z.object({ task: z.string() }),\n    component: SubAgentCallCardComponent,\n  };\n}\n",
  "src/app/features/subagents/subagents-chat.component.ts": "/**\n * \"Rendering a live delegation log\".\n * https://docs.copilotkit.ai/angular/mastra/multi-agent/subagents\n *\n * The class members between the region markers are the guide's snippet,\n * unchanged. Everything else is SELF-DEFINED: the guide shows class members\n * only, and reads `this.agentId` and `this.feature` without declaring them.\n * `agentId` is the runtime key server.ts registers the supervisor under;\n * `feature` is \"subagents\" so the snippet's branch runs. The delegation log\n * template is this harness's own — the guide's renders it in React\n * (delegation-log.tsx in its demo-code tab).\n */\nimport { Component, computed } from '@angular/core';\nimport {\n  CopilotChat,\n  injectAgentStore,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\n\nimport { type SubAgentName, readDelegations } from './subagent-model';\nimport { subAgentRendererConfig } from './subagent-renderer-config';\n\n@Component({\n  selector: 'app-subagents-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 0.75rem\">\n      <section\n        style=\"width: 22rem; overflow: auto; padding: 0.75rem\"\n        aria-label=\"Delegation log\"\n        data-testid=\"delegation-log\"\n      >\n        <h2 class=\"text-sm font-semibold text-slate-900\">\n          Delegations ({{ delegations().length }})\n        </h2>\n        <ol class=\"mt-2 space-y-2\">\n          @for (d of delegations(); track d.id) {\n            <li\n              class=\"rounded-lg border border-slate-200 bg-white p-2 text-sm\"\n              [attr.data-status]=\"d.status\"\n            >\n              <p class=\"font-semibold\">{{ d.sub_agent }} · {{ d.status }}</p>\n              <p class=\"text-slate-600\">{{ d.task }}</p>\n              <p class=\"mt-1 whitespace-pre-wrap text-slate-800\">\n                {{ d.result }}\n              </p>\n            </li>\n          }\n        </ol>\n      </section>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat [agentId]=\"agentId\" />\n      </div>\n    </div>\n  `,\n})\nexport class SubagentsChatComponent {\n  protected readonly agentId = 'subagents';\n  protected readonly feature: string = 'subagents';\n\n  // subagents : \"Rendering a live delegation log\" start\n  private readonly agentStore = injectAgentStore(this.agentId);\n  protected readonly delegations = computed(() =>\n    readDelegations(this.agentStore().state()),\n  );\n\n  constructor() {\n    if (this.feature === \"subagents\") {\n      this.registerSubAgent(\"research_agent\");\n      this.registerSubAgent(\"writing_agent\");\n      this.registerSubAgent(\"critique_agent\");\n    }\n  }\n\n  private registerSubAgent(name: SubAgentName): void {\n    registerRenderToolCall(subAgentRendererConfig(name));\n  }\n  // subagents : \"Rendering a live delegation log\" end\n}\n",
  "src/app/features/threads/conversations.component.ts": "/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/mastra/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n",
  "src/app/features/threads/thread-list.component.ts": "/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/guides/threads-memory-attachments-headless\n */\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\n * list on `injectThreads`, and the drop-in drawer beside a chat.\n */\nimport { Component } from '@angular/core';\n\nimport { ConversationsComponent } from './conversations.component';\nimport { ThreadListComponent } from './thread-list.component';\n\n@Component({\n  selector: 'app-threads-demo',\n  imports: [ThreadListComponent, ConversationsComponent],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <section class=\"rounded-lg border border-slate-200 bg-white p-4\">\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          Headless list — injectThreads\n        </h2>\n        <app-thread-list />\n      </section>\n\n      <section\n        class=\"flex min-h-0 flex-1 flex-col rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          CopilotThreadsDrawer + chat\n        </h2>\n        <div class=\"flex min-h-0 flex-1 gap-4\">\n          <app-conversations />\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class ThreadsDemoComponent {}\n",
  "src/app/features/tools/incident-card.component.ts": "/**\n * \"Let the agent display one of your components\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/guides/frontend-tools-generative-ui\n */\nimport { Component, input } from \"@angular/core\";\nimport { AngularToolCall, ToolRenderer } from \"@copilotkit/angular\";\n\ntype IncidentArgs = { id: string; severity: string };\n\n@Component({\n  selector: \"app-incident-card\",\n  standalone: true,\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"in-progress\") {\n      <p>Loading incident…</p>\n    } @else {\n      <article>\n        <strong>{{ call.args.id }}</strong>\n        <span>{{ call.args.severity }}</span>\n      </article>\n    }\n  `,\n})\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\n}\n",
  "src/app/features/tools/tool-feature-model.ts": "/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/mastra/guides/frontend-tools-generative-ui\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\nimport { type WritableSignal } from '@angular/core';\nimport { type FrontendToolConfig } from '@copilotkit/angular';\nimport { z } from 'zod';\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = {\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string {\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: 'change_background',\n    description: 'Change the application background to a CSS gradient.',\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n",
  "src/app/features/tools/tools-chat.component.ts": "/**\n * Mounts both halves of the guide's frontend-tools section against one chat.\n *\n * `registerRenderToolCall` — the tool runs on the server (the Agent Framework\n * agent's weather tool) and the browser only renders its call, through\n * WeatherCardComponent.\n *\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\n * has a handler and no component, so it renders nothing in chat; its result is\n * the page itself changing. The registration is removed when this injector is\n * destroyed.\n *\n * `registerComponent` — the guide's new first section: a component the agent\n * displays, with no handler and nothing on the agent side. `show_incident` is\n * declared here by the frontend and forwarded to the Mastra agent over AG-UI,\n * so the agent definition never learns about it. Needs @copilotkit/angular\n * 0.5.0 or newer; this repo runs 0.5.1.\n *\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\n * that runs in the browser. It is not mounted: it would collide with the\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\n * this repo does not serve.\n *\n * https://docs.copilotkit.ai/angular/mastra/guides/frontend-tools-generative-ui\n */\nimport { Component, signal } from '@angular/core';\nimport {\n  CopilotSidebar,\n  registerComponent,\n  registerFrontendTool,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport {\n  DEFAULT_BACKGROUND,\n  createBackgroundTool,\n} from './tool-feature-model';\nimport { IncidentCardComponent } from './incident-card.component';\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tools-chat',\n  imports: [CopilotSidebar],\n  template: `\n    <div\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n        <copilot-sidebar />\n\n    </div>\n  `,\n})\nexport class ToolsChatComponent {\n  /** Written by the agent through the change_background handler. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    registerRenderToolCall({\n      name: 'getWeather',\n      args: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n    });\n\n    registerFrontendTool(createBackgroundTool(this.background));\n\n    registerComponent({\n      name: \"show_incident\",\n      description: \"Show one incident from the incident table.\",\n      parameters: z.object({\n        id: z.string().describe(\"The incident id, such as INC-4711\"),\n        severity: z.string().describe(\"One of sev1, sev2, sev3\"),\n      }),\n      component: IncidentCardComponent,\n    });\n  }\n}\n",
  "src/app/features/tools/weather-card.component.ts": "/**\n * \"Render a tool result\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/guides/frontend-tools-generative-ui\n */\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: 'app-weather-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n    <p>Tool Call done </p>\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n",
  "../backend/src/mastra/agents/agent.ts": "import { pathToFileURL } from 'node:url';\nimport { Agent } from '@mastra/core/agent';\nimport { TaskSignalProvider } from '@mastra/core/signals';\nimport { askUserTool, webFetchTool, webSearchTool } from '@mastra/core/tools';\nimport { LocalFilesystem, LocalSandbox, WORKSPACE_TOOLS, Workspace } from '@mastra/core/workspace';\nimport { Memory } from '@mastra/memory';\nimport { startScheduleTool, stopScheduleTool } from '../tools/schedule-tools';\n\nconst workspacePath = 'workspace';\n\nconst workspace = new Workspace({\n  id: 'agent-workspace',\n  name: 'Agent Workspace',\n  filesystem: new LocalFilesystem({\n    basePath: workspacePath,\n  }),\n  sandbox: new LocalSandbox({\n    workingDirectory: workspacePath,\n  }),\n  tools: {\n    [WORKSPACE_TOOLS.FILESYSTEM.WRITE_FILE]: {\n      requireReadBeforeWrite: true,\n    },\n    [WORKSPACE_TOOLS.FILESYSTEM.EDIT_FILE]: {\n      requireReadBeforeWrite: true,\n    },\n    [WORKSPACE_TOOLS.FILESYSTEM.DELETE]: {\n      requireApproval: true,\n    },\n  },\n});\n\nexport const agent = new Agent({\n  id: 'agent',\n  name: 'Agent',\n  description:\n    'A general-purpose assistant that can research, manage tasks, work with local files, run approved commands, and create recurring schedules.',\n  metadata: {\n    suggestedPrompts: [\n      \"What's the weather in Austin this weekend?\",\n      \"What's the SPCX stock price right now?\",\n      'Build a Japanese sakura festival landing page.',\n    ],\n  },\n  instructions: `You are a friendly starter agent for exploring what Mastra can do. Help the user try useful capabilities, build small projects, answer current questions, and shape this harness into a starting point for future work.\n\nSuggested prompts: Get the weather forecast for your city; Create a Japanese Sakura festival page; Tell me the SPCX stock price now, then every minute.\n\nWhen the user greets you or does not have a specific task, invite them to try the suggested prompts.\n\nAsk concise questions when something is unclear or a good question could surface a useful insight.\n\nFor local file changes, end with a plain-text URL using ${pathToFileURL(`${workspacePath}/`).href}; avoid Markdown links, localhost, /workspace, relative paths, and static-file servers.\n`,\n  model: 'openai/gpt-5.4-mini',\n  defaultOptions: {\n    maxSteps: 100,\n    autoResumeSuspendedTools: true,\n  },\n  memory: new Memory({\n    options: {\n      generateTitle: true,\n      observationalMemory: {\n        model: 'openai/gpt-5.4-mini',\n      },\n    },\n  }),\n  workspace,\n  tools: {\n    ask_user: askUserTool,\n    start_schedule: startScheduleTool,\n    stop_schedule: stopScheduleTool,\n    web_fetch: webFetchTool,\n    web_search: webSearchTool,\n  },\n  signals: [new TaskSignalProvider()],\n});\n",
  "../backend/src/mastra/agents/index.ts": "import { openai } from \"@ai-sdk/openai\";\nimport { Agent } from \"@mastra/core/agent\";\nimport { createTool } from \"@mastra/core/tools\";\nimport { z } from \"zod\";\nimport { runDeepResearchTool } from \"../tools/background-research\"; // [!code highlight]\n\nexport const getWeather = createTool({\n  id: \"getWeather\",\n  inputSchema: z.object({\n    location: z.string(),\n  }),\n  description: `Fetches the current weather information for a given location`,\n  execute: async ({ location }) => {\n    // Tool logic here (e.g., API call)\n    console.log(\"Using tool to fetch weather information for\", location);\n    return { temperature: 20, conditions: \"Sunny\" }; // Example return\n  },\n});\n\nexport const myAgent = new Agent({\n  id: \"myAgent\",\n  name: \"My Agent\",\n  instructions: \"You are a helpful assistant!\",\n  model: openai(\"gpt-5.4-mini\"),\n  tools: {\n    getWeather,\n  },\n});\n\n// background-tasks : \"Add the tool to your agent\" start\n// https://docs.copilotkit.ai/angular/mastra/background-tasks\n// Verbatim except the import path: the guide imports\n// \"@/mastra/tools/background-research\", an alias this repo's tsconfig does\n// not define, so it is the equivalent relative path here.\nexport const backgroundAgentsAgent = new Agent({\n  id: \"background-agents\",\n  name: \"Background Agents Agent\",\n  tools: { runDeepResearchTool }, // [!code highlight]\n  model: openai(\"gpt-4.1\"),\n  instructions:\n    \"You are a research assistant that dispatches long-running work to the \" +\n    \"background. When the user asks you to research a topic, call the \" +\n    \"run_deep_research tool ONCE, then send a short message saying the work \" +\n    \"is running in the background.\",\n});\n// background-tasks : \"Add the tool to your agent\" end\n",
  "../backend/src/mastra/agents/subagents-supervisor.ts": "// subagents : supervisor agent start\n// Not in the guide's text. Copied from the guide's own demo-code tab\n// (\"src/mastra/agents/index.ts\") at\n// https://docs.copilotkit.ai/angular/mastra/multi-agent/subagents — only the\n// pieces the supervisor needs. Changes from that file:\n//   - imports trimmed to what these pieces use;\n//   - the \"@/mastra/tools\" barrel import is the relative \"../tools/subagents\"\n//     (the alias is not defined in this repo);\n//   - \"@/mastra/_header_forwarding\" is left as published and does not resolve.\n// Not registered in ./index.ts: server.ts loads it behind a guard.\n\n// Header-forwarding shim: the ag-ui/mastra adapter does not propagate\n// inbound x-* headers (e.g. x-aimock-context) to the Vercel AI SDK provider.\n// `@/mastra/_header_forwarding` re-exports `openai` with a fetch wrapper\n// that merges ALS-bound headers into every outbound LLM call. The\n// CopilotKit route is responsible for binding the per-request snapshot via\n// `withForwardedHeaders(req, () => handleRequest(req))`.\nimport { openai } from \"@/mastra/_header_forwarding\";\nimport { Agent } from \"@mastra/core/agent\";\nimport { LibSQLStore } from \"@mastra/libsql\";\nimport { z } from \"zod\";\nimport { Memory } from \"@mastra/memory\";\nimport {\n  researchAgentTool,\n  writingAgentTool,\n  critiqueAgentTool,\n} from \"../tools/subagents\";\n\n/**\n * Persistent SQLite URL for working-memory storage.\n *\n * Why not `file::memory:`: an in-memory store resets on every process\n * restart. For demos that surface user state to the UI (notes panel, agent\n * delegations, preferences), that is silent data loss — the user adds notes,\n * the dev hits save, Next.js HMR restarts the server, and the notes vanish\n * with no error.\n *\n * Tests can override via `MASTRA_WORKING_MEMORY_URL=file::memory:` to keep\n * fixture isolation. The default is a relative file path so the DB lives\n * next to the package and survives reloads.\n */\nexport const WORKING_MEMORY_DB_URL =\n  process.env.MASTRA_WORKING_MEMORY_URL ?? \"file:./mastra-memory.db\";\n\n/**\n * Shared-state schema for the Sub-Agents demo.\n *\n * `delegations` is appended to by the supervisor as it fans out work to the\n * research / writing / critique sub-agents. The UI subscribes via\n * `useAgent({ updates: [OnStateChanged] })` and renders a live delegation\n * log.\n */\nexport const SubagentsAgentState = z.object({\n  delegations: z\n    .array(\n      z.object({\n        id: z.string(),\n        sub_agent: z.enum([\n          \"research_agent\",\n          \"writing_agent\",\n          \"critique_agent\",\n        ]),\n        task: z.string(),\n        status: z.enum([\"running\", \"completed\", \"failed\"]),\n        result: z.string(),\n      }),\n    )\n    .default([]),\n});\n\n/**\n * Mastra agent backing the Sub-Agents demo.\n *\n * Supervisor pattern: this agent delegates to three specialized sub-agents\n * (research / writing / critique) exposed as tools. Each tool runs the\n * matching sub-agent under the hood and returns both its output and a\n * `delegation` entry the supervisor must append to working memory's\n * `delegations` array. The UI renders that array live as a delegation log.\n *\n * Sub-agents are defined alongside the tools in\n * `src/mastra/tools/subagents.ts` — they're full `Agent` instances with\n * their own system prompts and don't share memory with the supervisor.\n */\nexport const subagentsSupervisorAgent = new Agent({\n  id: \"subagents-supervisor\",\n  name: \"Subagents Supervisor\",\n  tools: {\n    researchAgentTool,\n    writingAgentTool,\n    critiqueAgentTool,\n  },\n  model: openai(\"gpt-5-mini\"),\n  instructions: `You are a supervisor agent that coordinates three specialized sub-agents to produce high-quality deliverables.\n\nAvailable sub-agents (call them as tools):\n  - research_agent: gathers facts on a topic.\n  - writing_agent: turns facts + a brief into a polished draft.\n  - critique_agent: reviews a draft and suggests improvements.\n\nFor most non-trivial user requests, delegate in sequence: research -> write -> critique. Pass the relevant facts/draft through the \\`task\\` argument of each tool. Keep your own messages short — explain the plan once, delegate, then return a concise summary once done.\n\nDELEGATION LOG (working memory):\nEach sub-agent tool returns a JSON payload of the form \\`{ \"result\": <text>, \"delegation\": <Delegation> }\\`. The tool itself appends the \\`delegation\\` object to the \\`delegations\\` array in working memory — you do NOT need to call \\`updateWorkingMemory\\` for delegations. Just keep delegating; the live log updates automatically.\n\nIf a delegation's \\`status\\` field is \\`\"failed\"\\`, treat it as a real error: do not pretend the sub-agent succeeded. Decide whether to retry, fall back to a different sub-agent, or summarize the failure to the user.`,\n  memory: new Memory({\n    storage: new LibSQLStore({\n      id: \"subagents-supervisor-memory\",\n      url: WORKING_MEMORY_DB_URL,\n    }),\n    options: {\n      workingMemory: {\n        enabled: true,\n        schema: SubagentsAgentState,\n      },\n    },\n  }),\n});\n\n// subagents : supervisor agent end\n",
  "../backend/src/mastra/index.ts": "// background-tasks : \"Enable the BackgroundTaskManager on the Mastra instance\" start\n// https://docs.copilotkit.ai/angular/mastra/background-tasks\n// The guide's instance holds only `backgroundAgentsAgent`; `myAgent` is this\n// harness's existing agent, kept alongside it in the same record.\nimport { Mastra } from \"@mastra/core/mastra\";\nimport { LibSQLStore } from \"@mastra/libsql\";\nimport { myAgent, backgroundAgentsAgent } from \"./agents\";\n\nexport const mastra = new Mastra({\n  agents: { myAgent, backgroundAgentsAgent },\n  storage: new LibSQLStore({ id: \"mastra-storage\", url: \":memory:\" }),\n  backgroundTasks: { enabled: true }, // [!code highlight]\n});\n// background-tasks : \"Enable the BackgroundTaskManager on the Mastra instance\" end\n",
  "../backend/src/mastra/tools/background-research.ts": "/**\n * \"Define a backgroundable tool\", verbatim.\n * https://docs.copilotkit.ai/angular/mastra/background-tasks\n */\nimport { createTool } from \"@mastra/core/tools\";\nimport { z } from \"zod\";\n\nexport const runDeepResearchTool = createTool({\n  id: \"run_deep_research\",\n  description:\n    \"Kick off a long-running deep-research task on a topic. This runs in \" +\n    \"the background while the conversation continues.\",\n  inputSchema: z.object({\n    topic: z.string().describe(\"The topic to research in depth.\"),\n  }),\n  background: { enabled: true }, // [!code highlight]\n  execute: async ({ topic }) => {\n    // Runs when the background worker executes the task.\n    return JSON.stringify({\n      topic,\n      summary: `Deep research on \"${topic}\" completed.`,\n    });\n  },\n});\n",
  "../backend/src/mastra/tools/schedule-tools.ts": "import { createTool } from '@mastra/core/tools';\nimport { z } from 'zod';\n\nexport const startScheduleTool = createTool({\n  id: 'start_schedule',\n  description: 'Start a recurring schedule for the default agent.',\n  inputSchema: z.object({\n    schedule: z.string().describe('Cron expression for when to run.'),\n    prompt: z.string().describe('Prompt to run on the schedule.'),\n  }),\n  execute: async ({ schedule, prompt }, { mastra, agent }) => {\n    if (!agent?.threadId || !agent.resourceId) {\n      throw new Error('A threadId and resourceId are required to create a schedule.');\n    }\n\n    return mastra!.schedules.create({\n      agentId: 'agent',\n      cron: schedule,\n      prompt,\n      threadId: agent.threadId,\n      resourceId: agent.resourceId,\n    });\n  },\n});\n\nexport const stopScheduleTool = createTool({\n  id: 'stop_schedule',\n  description: 'Stop a schedule by pausing it.',\n  inputSchema: z.object({\n    scheduleId: z.string().describe('Schedule id returned by start_schedule.'),\n  }),\n  execute: async ({ scheduleId }, { mastra }) => mastra!.schedules.pause(scheduleId),\n});\n",
  "../backend/src/mastra/tools/subagents.ts": "// subagents : \"Exposing sub-agents as tools\" start\n// https://docs.copilotkit.ai/angular/mastra/multi-agent/subagents\n// Verbatim. Two imports are left exactly as published and resolve to nothing:\n// \"@/mastra/_header_forwarding\" (an alias this repo does not define, for a\n// file the guide never shows) and \"./working-memory\" (never shown either).\n// This module therefore cannot load; server.ts imports it behind a guard so\n// the failure stays confined to the sub-agents runtime keys.\n// src/mastra/tools/subagents.ts\nimport { createTool } from \"@mastra/core/tools\";\nimport { z } from \"zod\";\n// Use the header-forwarding `openai` so subagents' internal LLM calls\n// carry the inbound `x-aimock-context` / `x-aimock-strict` headers. Without\n// this, sub-agent calls return 404 from aimock under strict mode. See\n// `_header_forwarding.ts` for the ALS-bound fetch wrapper.\nimport { openai } from \"@/mastra/_header_forwarding\";\nimport { Agent } from \"@mastra/core/agent\";\nimport crypto from \"node:crypto\";\nimport { writeDelegationsToWorkingMemory } from \"./working-memory\";\n\n// Each sub-agent is a full Mastra `Agent` with its own system prompt. They\n// don't share memory or tools with the supervisor — the supervisor only sees\n// their final text output via the tools below. Mirrors the LangGraph-Python\n// `subagents.py` reference where each sub-agent is a `create_agent(...)`.\nconst SUBAGENT_MODEL = openai(\"gpt-5-mini\");\n\nconst researchSubAgent = new Agent({\n  id: \"research-subagent\",\n  name: \"Research Subagent\",\n  model: SUBAGENT_MODEL,\n  instructions:\n    \"You are a research sub-agent. Given a topic, produce a concise \" +\n    \"bulleted list of 3-5 key facts. No preamble, no closing.\",\n});\n\nconst writingSubAgent = new Agent({\n  id: \"writing-subagent\",\n  name: \"Writing Subagent\",\n  model: SUBAGENT_MODEL,\n  instructions:\n    \"You are a writing sub-agent. Given a brief and optional source \" +\n    \"facts, produce a polished 1-paragraph draft. Be clear and concrete. \" +\n    \"No preamble.\",\n});\n\nconst critiqueSubAgent = new Agent({\n  id: \"critique-subagent\",\n  name: \"Critique Subagent\",\n  model: SUBAGENT_MODEL,\n  instructions:\n    \"You are an editorial critique sub-agent. Given a draft, give 2-3 \" +\n    \"crisp, actionable critiques. No preamble.\",\n});\n\n/**\n * Result of invoking a sub-agent. Discriminated so the wrapping tools can map\n * success/failure into the correct delegation `status` for the UI without\n * relying on string-matching the `result` field. We deliberately do NOT\n * surface raw `err.message` to the LLM/UI: error messages from upstream APIs\n * routinely leak api keys, file paths, and prompt contents. Mirror the\n * agno / claude-sdk-python pattern of redacting to the error class name.\n */\ntype SubAgentResult = { ok: true; text: string } | { ok: false; error: string };\n\nasync function invokeSubAgent(\n  agent: Agent,\n  task: string,\n): Promise<SubAgentResult> {\n  // Mastra Agent.generate returns an object with a `.text` field for the\n  // final assistant text. We catch internally so a sub-agent failure becomes\n  // a visible failed delegation entry rather than crashing the supervisor.\n  try {\n    const result = await agent.generate(task);\n    const text = (result as { text?: unknown }).text;\n    return {\n      ok: true,\n      text: typeof text === \"string\" && text.length > 0 ? text : \"\",\n    };\n  } catch (err) {\n    // Redact: only the error class name reaches the LLM and the UI. The full\n    // `err.message` (which can contain provider keys, file paths, or echoed\n    // prompts) stays in the server log below.\n    const errorClass =\n      err instanceof Error ? err.constructor.name : \"UnknownError\";\n    console.error(\n      JSON.stringify({\n        at: new Date().toISOString(),\n        level: \"error\",\n        component: \"subagents\",\n        agentId: agent.id,\n        errorClass,\n        message: err instanceof Error ? err.message : String(err),\n        stack: err instanceof Error ? err.stack : undefined,\n      }),\n    );\n    return { ok: false, error: errorClass };\n  }\n}\n\n/**\n * Delegate a research task to the research sub-agent.\n *\n * The supervisor LLM \"calls\" this tool to fan a research subtask out. The\n * tool synchronously runs the matching Mastra sub-agent and returns a\n * `Delegation` entry. The supervisor is instructed to APPEND this entry to\n * the `delegations` array in working memory so the UI's live delegation log\n * picks it up via the AG-UI state-snapshot channel.\n */\ntype SubAgentName = \"research_agent\" | \"writing_agent\" | \"critique_agent\";\n\n/**\n * Build the delegation entry + tool-result payload from a SubAgentResult.\n *\n * Status mapping rules (the whole point of `SubAgentResult`):\n *   - ok: true  → status = \"completed\", result = sub-agent text output\n *   - ok: false → status = \"failed\",    result = \"[sub-agent error] <ErrorClass>\"\n *\n * Without this discrimination, a sub-agent that throws renders as a green\n * \"completed\" entry in the UI's delegation log — a UX lie the supervisor LLM\n * cannot detect either, since it sees the same green payload. Surfacing the\n * redacted error class through the `result` field lets the supervisor decide\n * to retry or fall back, without leaking provider-side internals.\n */\nfunction buildDelegationPayload(\n  subAgentName: SubAgentName,\n  task: string,\n  result: SubAgentResult,\n): { delegation: Record<string, unknown>; resultText: string } {\n  const resultText = result.ok\n    ? result.text\n    : `[sub-agent error] ${result.error}`;\n  const delegation = {\n    id: crypto.randomUUID(),\n    sub_agent: subAgentName,\n    task,\n    status: result.ok ? (\"completed\" as const) : (\"failed\" as const),\n    result: resultText,\n  };\n  return { delegation, resultText };\n}\n\nexport const researchAgentTool = createTool({\n  id: \"research_agent\",\n  description:\n    \"Delegate a research task to the research sub-agent. Use for: \" +\n    \"gathering facts, background, definitions, statistics. Returns a \" +\n    \"bulleted list of key facts. The delegation is also recorded directly \" +\n    \"in working memory by the tool itself — you do not need to (and \" +\n    \"should not) re-emit the delegation object.\",\n  inputSchema: z.object({\n    task: z.string().describe(\"The research task / topic to investigate.\"),\n  }),\n  execute: async (inputData, executionContext) => {\n    const task = inputData.task ?? \"\";\n    const result = await invokeSubAgent(researchSubAgent, task);\n    const { delegation, resultText } = buildDelegationPayload(\n      \"research_agent\",\n      task,\n      result,\n    );\n    await writeDelegationsToWorkingMemory(executionContext, delegation);\n    return JSON.stringify({ result: resultText, delegation });\n  },\n});\n\nexport const writingAgentTool = createTool({\n  id: \"writing_agent\",\n  description:\n    \"Delegate a drafting task to the writing sub-agent. Use for: producing \" +\n    \"a polished paragraph, draft, or summary. Pass relevant facts from \" +\n    \"prior research inside `task`. Returns the draft. The delegation is \" +\n    \"also recorded directly in working memory by the tool itself.\",\n  inputSchema: z.object({\n    task: z\n      .string()\n      .describe(\n        \"The drafting brief, including any facts the writer should incorporate.\",\n      ),\n  }),\n  execute: async (inputData, executionContext) => {\n    const task = inputData.task ?? \"\";\n    const result = await invokeSubAgent(writingSubAgent, task);\n    const { delegation, resultText } = buildDelegationPayload(\n      \"writing_agent\",\n      task,\n      result,\n    );\n    await writeDelegationsToWorkingMemory(executionContext, delegation);\n    return JSON.stringify({ result: resultText, delegation });\n  },\n});\n\nexport const critiqueAgentTool = createTool({\n  id: \"critique_agent\",\n  description:\n    \"Delegate a critique task to the critique sub-agent. Use for: \" +\n    \"reviewing a draft and suggesting concrete improvements. Returns the \" +\n    \"critique. The delegation is also recorded directly in working memory \" +\n    \"by the tool itself.\",\n  inputSchema: z.object({\n    task: z\n      .string()\n      .describe(\n        \"The draft to critique, plus any specific critique focus you want.\",\n      ),\n  }),\n  execute: async (inputData, executionContext) => {\n    const task = inputData.task ?? \"\";\n    const result = await invokeSubAgent(critiqueSubAgent, task);\n    const { delegation, resultText } = buildDelegationPayload(\n      \"critique_agent\",\n      task,\n      result,\n    );\n    await writeDelegationsToWorkingMemory(executionContext, delegation);\n    return JSON.stringify({ result: resultText, delegation });\n  },\n});\n// subagents : \"Exposing sub-agents as tools\" end\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
